//   Phase 2 (constrained loop):
//     - CloseSpanIfComplete closed: insideConstrainedOut := false, invariant vacuous; cc = [] ✓
//     - SafePenalizedConstrainedStep + AppendConstrainedToken: AppendConstrainedToken postcondition
//       guarantees parser.IsValidPrefix(currentConstrainedOut + [next]) when next != eosToken ✓
//     - EOS branch: generated/insideConstrainedOut/currentConstrainedOut unchanged ✓
//   Phase 3: CloseSpanWithinBudget postcondition guarantees invariant ✓
//   Phase 4: OpenConstrainedSpan sets currentConstrainedOut := []; IsValidPrefix([]) holds ✓
//   Phase 5: same argument as Phase 2 ✓
//   Phase 6: same as Phase 3 ✓
// progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: UnconstrainedChunk adds stepsUsed to steps, |generatedOut| <= |generated| + stepsUsed ✓
//   Phase 2: Each non-break iteration: SafePenalizedConstrainedStep costs 1 step; AppendConstrainedToken
//     adds 1 token. CloseSpanIfComplete (closed) adds at most 1 token and costs 1 step. All paths ✓
//   Phase 3: closeBudget = maxSteps - steps_before; CloseSpanWithinBudget post: |generatedOut| <=
//     |generated_before| + closeBudget; steps := steps_before + closeBudget = maxSteps ✓
//   Phase 4: OpenConstrainedSpan adds 1 token ("<<"), steps += 1 ✓
//   Phase 5: same as Phase 2 ✓  Phase 6: same as Phase 3 ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

