  return;
}

var guidance: string := "Solve step by step using the variable names from the problem WITHOUT curly braces. At the end write: The answer is <<EXPR>> where EXPR is the COMPLETE arithmetic expression with ALL variables and ALL operations. For 'N times as many as Y', write Y*N. Use only +, -, *, /, (, ). No LaTeX.";
