var hasCompletedSpan: bool := false;
var minInner: nat := 5;
var innerLimit: nat := 80;
var eosTokens: seq<Token> := [eosToken];

var freeLimit: nat := (maxSteps * 65) / 100;
if freeLimit == 0 {
  freeLimit := 1;
}
if freeLimit > maxSteps {
  freeLimit := maxSteps;
}

