  while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerCount2 < innerLimit
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases (maxSteps - steps) + (innerLimit - innerCount2)
  {
    if innerTokCount2 >= minInner {
      var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      if closed2 {
        generated := cg2;
        insideConstrainedOut := ci2;
        currentConstrainedOut := cc2;
        steps := steps + 1;
        hasCompletedSpan := true;
        break;
      }
    }
    var constrainedPrompt2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next2 := helpers.SafePenalizedConstrainedStep(lm, parser, constrainedPrompt2, currentConstrainedOut, eosTokens, 8.0, eosToken);
    steps := steps + 1;
    innerCount2 := innerCount2 + 1;
    if next2 == eosToken {
      break;
    }
    var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
    generated := ag2;
    insideConstrainedOut := ai2;
    currentConstrainedOut := ac2;
    innerTokCount2 := innerTokCount2 + 1;
  }

  // Phase 6: Use all remaining budget to close the forced span
  if insideConstrainedOut && steps < maxSteps {
    var finalBudget: nat := maxSteps - steps;
    var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, finalBudget);
    generated := wg2;
    insideConstrainedOut := wi2;
    currentConstrainedOut := wc2;
    steps := steps + finalBudget;
  }
}

